using Ecom.Domain.Entities;

namespace Ecom.Application.Features.Commerce.Producers.Commands.CreateProducerContact;
public sealed record CreateProducerContactCommand(Guid ProducerId,Guid ProducerConcurrencyStamp,ContactType ContactType,string ContactValue,string? ContactName,bool IsPublic,int DisplayOrder):IRequest<TResult<ProducerContactDto>>,ITransactionalRequest;
public sealed class CreateProducerContactCommandValidator:AbstractValidator<CreateProducerContactCommand>{public CreateProducerContactCommandValidator(){RuleFor(x=>x.ProducerId).NotEmpty();RuleFor(x=>x.ProducerConcurrencyStamp).NotEmpty();RuleFor(x=>x.ContactValue).NotEmpty().MaximumLength(512);RuleFor(x=>x.ContactName).MaximumLength(256);RuleFor(x=>x.DisplayOrder).GreaterThanOrEqualTo(0);}}
public sealed class CreateProducerContactCommandHandler(IUnitOfWork uow,ProducerManagementService service):IRequestHandler<CreateProducerContactCommand,TResult<ProducerContactDto>>
{public async Task<TResult<ProducerContactDto>> Handle(CreateProducerContactCommand r,CancellationToken ct){var loaded=await service.LoadAsync(r.ProducerId,r.ProducerConcurrencyStamp,Permissions.Producers.Update,ct);if(!loaded.IsSuccess)return TResult<ProducerContactDto>.Failure(loaded.Error!,loaded.ErrorCode);var contact=ProducerContact.Create(loaded.Data.Id,r.ContactType,r.ContactValue,r.ContactName,r.IsPublic,r.DisplayOrder);loaded.Data.RenewConcurrencyStamp();await uow.Repository<ProducerContact>().InsertAsync(contact,ct);await uow.Repository<Producer>().UpdateAsync(loaded.Data,ct);return TResult<ProducerContactDto>.Success(ProducerManagementService.Map(contact));}}
